function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (edges.length > n * (n - 1) / 2) return 'There are at most n * (n - 1) / 2 edges.';
  const indegree = new Array(n).fill(0);
  const out = Array.from({ length: n }, () => []);
  for (const edge of edges) {
    if (edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (![u, v].every(x => Number.isInteger(x) && x >= 0 && x < n)) return 'Edge ends are teams 0 to n - 1.';
    if (u === v) return 'An edge joins two different teams.';
    out[u].push(v);
    indegree[v]++;
  }
  const queue = [];
  for (let i = 0; i < n; i++) if (indegree[i] === 0) queue.push(i);
  let removed = 0;
  while (queue.length) { const u = queue.pop(); removed++; for (const v of out[u]) if (--indegree[v] === 0) queue.push(v); }
  if (removed !== n) return 'The edges must not form a cycle.';
  return null;
}

