function findChampion(n, edges) {
  const indegree = new Array(n).fill(0);
  for (const [, weaker] of edges) {
    indegree[weaker]++;
  }
  let champion = -1;
  for (let team = 0; team < n; team++) {
    if (indegree[team] === 0) {
      if (champion !== -1) {
        return -1;
      }
      champion = team;
    }
  }
  return champion;
}

