function findChampion(n, edges) {
  // Build the full "stronger than" relation with a transitive closure, then test every team.
  const beats = Array.from({ length: n }, () => new Array(n).fill(false));
  for (const [u, v] of edges) beats[u][v] = true;
  for (let mid = 0; mid < n; mid++)
    for (let a = 0; a < n; a++)
      for (let b = 0; b < n; b++)
        if (beats[a][mid] && beats[mid][b]) beats[a][b] = true;
  const champions = [];
  for (let team = 0; team < n; team++) {
    let beaten = false;
    for (let other = 0; other < n; other++) if (beats[other][team]) beaten = true;
    if (!beaten) champions.push(team);
  }
  return champions.length === 1 ? champions[0] : -1;
}

