function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 7);
  // A random order of the teams; edges only go from earlier to later teams, so there is no cycle.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  const density = size === 'large' ? 0.05 + rand() * 0.3 : rand();
  const crown = rand() < 0.5;
  const limit = size === 'large' ? 2000 : Infinity;
  const edges = [];
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      if ((crown && i === 0) || rand() < density) edges.push([order[i], order[j]]);
  for (let i = edges.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  return [n, edges.slice(0, limit)];
}
